  { state: "Ohio", abbr: "OH", region: "Midwest", expansion: "expanded", rate2023: 8.4, rate2024: 9.1, deltaPp: 0.7, significant: true, uninsuredM: 0.62, confidence: "disclosed" },
  { state: "Oklahoma", abbr: "OK", region: "South", expansion: "expanded", rate2023: 16.1, rate2024: 15.9, deltaPp: -0.2, significant: false, uninsuredM: 0.38, confidence: "disclosed" },
  { state: "Oregon", abbr: "OR", region: "West", expansion: "expanded", rate2023: 8.0, rate2024: 7.6, deltaPp: -0.4, significant: false, uninsuredM: 0.19, confidence: "disclosed" },
  { state: "Pennsylvania", abbr: "PA", region: "Northeast", expansion: "expanded", rate2023: 7.1, rate2024: 7.8, deltaPp: 0.7, significant: true, uninsuredM: 0.58, confidence: "disclosed" },
  { state: "Rhode Island", abbr: "RI", region: "Northeast", expansion: "expanded", rate2023: 6.1, rate2024: 6.3, deltaPp: 0.2, significant: false, uninsuredM: 0.04, confidence: "disclosed" },
  { state: "South Carolina", abbr: "SC", region: "South", expansion: "non-expansion", rate2023: 13.2, rate2024: 13.1, deltaPp: -0.1, significant: false, uninsuredM: 0.40, confidence: "disclosed" },
  { state: "South Dakota", abbr: "SD", region: "Midwest", expansion: "expanded", rate2023: 11.3, rate2024: 10.6, deltaPp: -0.7, significant: false, uninsuredM: 0.05, confidence: "disclosed" },
  { state: "Tennessee", abbr: "TN", region: "South", expansion: "non-expansion", rate2023: 13.3, rate2024: 13.6, deltaPp: 0.3, significant: false, uninsuredM: 0.56, confidence: "disclosed" },
  { state: "Texas", abbr: "TX", region: "South", expansion: "non-expansion", rate2023: 21.7, rate2024: 21.6, deltaPp: -0.1, significant: false, uninsuredM: 4.10, confidence: "disclosed" },
  { state: "Utah", abbr: "UT", region: "West", expansion: "expanded", rate2023: 10.1, rate2024: 10.7, deltaPp: 0.5, significant: false, uninsuredM: 0.22, confidence: "disclosed" },
  { state: "Vermont", abbr: "VT", region: "Northeast", expansion: "expanded", rate2023: 5.0, rate2024: 6.3, deltaPp: 1.3, significant: true, uninsuredM: 0.02, confidence: "disclosed" },
  { state: "Virginia", abbr: "VA", region: "South", expansion: "expanded", rate2023: 8.7, rate2024: 9.5, deltaPp: 0.7, significant: true, uninsuredM: 0.50, confidence: "disclosed" },
  { state: "Washington", abbr: "WA", region: "West", expansion: "expanded", rate2023: 8.9, rate2024: 9.2, deltaPp: 0.3, significant: false, uninsuredM: 0.43, confidence: "disclosed" },
  { state: "West Virginia", abbr: "WV", region: "South", expansion: "expanded", rate2023: 9.1, rate2024: 9.0, deltaPp: -0.2, significant: false, uninsuredM: 0.09, confidence: "disclosed" },
  { state: "Wisconsin", abbr: "WI", region: "Midwest", expansion: "non-expansion", rate2023: 6.6, rate2024: 7.3, deltaPp: 0.7, significant: true, uninsuredM: 0.26, confidence: "disclosed" },
  { state: "Wyoming", abbr: "WY", region: "West", expansion: "non-expansion", rate2023: 15.6, rate2024: 14.2, deltaPp: -1.4, significant: false, uninsuredM: 0.05, confidence: "disclosed" },
];

export type VintageRow = {
  year: number;
  /** ACS national working-age (19???64) uninsured % */
  workingAgePct: number;
  /** ACS national all-ages uninsured % */
  allAgesPct: number;
  /** ACS Medicaid share all ages % */
  medicaidPct: number;
  note: string;
  confidence: Confidence;
};

/** National ACS path through continuous enrollment and unwinding */
export const NATIONAL_VINTAGE: VintageRow[] = [
  { year: 2019, workingAgePct: 12.9, allAgesPct: 9.2, medicaidPct: 19.8, note: "Pre-pandemic ACS", confidence: "carried" },
  { year: 2020, workingAgePct: 12.5, allAgesPct: 8.6, medicaidPct: 20.4, note: "Pandemic onset", confidence: "carried" },
  { year: 2021, workingAgePct: 11.6, allAgesPct: 8.3, medicaidPct: 21.0, note: "Continuous enrollment in force", confidence: "carried" },
  { year: 2022, workingAgePct: 11.2, allAgesPct: 8.0, medicaidPct: 21.2, note: "Coverage floor years", confidence: "carried" },
  { year: 2023, workingAgePct: 11.0, allAgesPct: 7.9, medicaidPct: 21.3, note: "Unwinding begins Apr 2023", confidence: "disclosed" },
  { year: 2024, workingAgePct: 11.3, allAgesPct: 8.2, medicaidPct: 20.5, note: "First full post-unwinding ACS year", confidence: "disclosed" },
];

export type AgeBandRow = {
  band: string;
  rate2024: number;
  note: string;
  confidence: Confidence;
};

/** CPS ASEC P60-288 working-age age bands (2024) */
export const AGE_BANDS: AgeBandRow[] = [
  { band: "19???25", rate2024: 14.3, note: "Highest working-age band", confidence: "disclosed" },
  { band: "26???34", rate2024: 12.1, note: "CPS ASEC desk band", confidence: "estimated" },
  { band: "35???44", rate2024: 10.8, note: "Significant YoY decline in CPS", confidence: "disclosed" },
  { band: "45???64", rate2024: 8.8, note: "Lowest working-age band", confidence: "disclosed" },
];

export type DemoRow = {
  group: string;
  rate2024: number;
  deltaNote: string;
  confidence: Confidence;
};

/** CPS ASEC working-age (19???64) by race/ethnicity, 2024 */
export const DEMO_GAPS: DemoRow[] = [
  { group: "Hispanic (any race)", rate2024: 23.0, deltaNote: "About 2?? Black; >3?? White NH", confidence: "disclosed" },
  { group: "Black", rate2024: 12.3, deltaNote: "+1.2 pp YoY (largest race change)", confidence: "disclosed" },
  { group: "Asian", rate2024: 6.9, deltaNote: "Statistically flat YoY", confidence: "disclosed" },
  { group: "White, non-Hispanic", rate2024: 6.8, deltaNote: "Lowest major group rate", confidence: "disclosed" },
];

export type ExpansionCompareRow = {
  group: string;
  rate2024: number;
  states: number;
  note: string;
};

/** Desk composite: ACS working-age mean weighted by uninsuredM within expansion status */
export const EXPANSION_COMPARE: ExpansionCompareRow[] = [
  {
    group: "Non-expansion (Jan 2024)",
    rate2024: 16.8,
    states: 10,
    note: "AL, FL, GA, KS, MS, SC, TN, TX, WI, WY ??? population-weighted desk mean",
  },
  {
    group: "Expansion states + DC",
    rate2024: 9.4,
    states: 41,
    note: "Includes recent expanders NC, SD, OK, MO ??? population-weighted desk mean",
  },
  {
    group: "United States",
    rate2024: 11.3,
    states: 51,
    note: "ACSBR-024 national working-age rate",
  },
];

export type RegionSummaryRow = {
  region: RegionId;
  meanRate2024: number;
  meanDeltaPp: number;
  statesAboveNational: number;
  topState: string;
  topRate: number;
};

function mean(nums: number[]): number {
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

export const REGION_SUMMARY: RegionSummaryRow[] = (
  ["South", "Midwest", "West", "Northeast"] as RegionId[]
).map((region) => {
  const rows = STATE_GAPS.filter((s) => s.region === region);
  const top = [...rows].sort((a, b) => b.rate2024 - a.rate2024)[0];
  return {
    region,
    meanRate2024: Math.round(mean(rows.map((r) => r.rate2024)) * 10) / 10,
    meanDeltaPp: Math.round(mean(rows.map((r) => r.deltaPp)) * 10) / 10,
    statesAboveNational: rows.filter((r) => r.rate2024 > HEADLINE.usWorkingAge2024).length,
    topState: top.abbr,
    topRate: top.rate2024,
  };
});

export type CoverageMixRow = {
  year: number;
  privatePct: number;
  publicPct: number;
  uninsuredPct: number;
  medicaidPct: number;
  confidence: Confidence;
};

/** ACS all-ages coverage mix (SHADAC / Census ACS S2701) */
export const COVERAGE_MIX: CoverageMixRow[] = [
  { year: 2023, privatePct: 67.0, publicPct: 37.4, uninsuredPct: 7.9, medicaidPct: 21.3, confidence: "disclosed" },
  { year: 2024, privatePct: 67.2, publicPct: 36.8, uninsuredPct: 8.2, medicaidPct: 20.5, confidence: "disclosed" },
];

export type JumpRow = {
  state: string;
  abbr: string;
  deltaPp: number;
  rate2024: number;
  direction: "up" | "down";
};

/** Largest absolute working-age deltas (significant or notable) */
export const BIGGEST_MOVES: JumpRow[] = [...STATE_GAPS]
  .filter((s) => s.significant || Math.abs(s.deltaPp) >= 1.0)
  .sort((a, b) => Math.abs(b.deltaPp) - Math.abs(a.deltaPp))
  .slice(0, 14)
  .map((s) => ({
    state: s.state,
    abbr: s.abbr,
    deltaPp: s.deltaPp,
    rate2024: s.rate2024,
    direction: s.deltaPp >= 0 ? "up" : "down",
  }));

export function statesByRegion(region: "all" | RegionId): StateGapRow[] {
  if (region === "all") return STATE_GAPS;
  return STATE_GAPS.filter((s) => s.region === region);
}

export function statesByExpansion(
  filter: "all" | ExpansionStatus,
): StateGapRow[] {
  if (filter === "all") return STATE_GAPS;
  return STATE_GAPS.filter((s) => s.expansion === filter);
}

export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

export function fmtM(n: number): string {
  return `${n.toFixed(2)}M`;
}

args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AGE_BANDS,
  BIGGEST_MOVES,
  DEMO_GAPS,
  EXPANSION_COMPARE,
  HEADLINE,
  NATIONAL_VINTAGE,
  REGION_SUMMARY,
  SOURCE_NOTE,
  STATE_GAPS,
  VIZ_MARKERS,
  fmtPct,
  fmtPp,
  statesByExpansion,
  statesByRegion,
  type ExpansionStatus,
  type RegionId,
} from "@/data/health-insurance-coverage-gaps-census-2026-data";

// viz-types: national composed area+line, state ladder bars,
// unwinding delta scatter, expansion compare bars, age/demo bars,
// biggest-moves diverging | layout: default
// smoke-marker: Working-age uninsured ??? Texas 21.6%

type ViewId =
  | "vintage"
  | "ladder"
  | "scatter"
  | "expansion"
  | "ages"
  | "moves";

type RegionFilter = "all" | RegionId;
type ExpansionFilter = "all" | ExpansionStatus;
type LadderSort = "rate" | "delta" | "headcount";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";

const REGION_COLORS: Record<string, string> = {
  South: ROSE,
  Midwest: TEAL,
  West: AMBER,
  Northeast: INDIGO,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  options,
  value,
  onChange,
}: {
  options: { id: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((o) => (
        <button
          key={o.id}
          type="button"
          onClick={() => onChange(o.id)}
          className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
            value === o.id
              ? "bg-slate-900 text-white"
              : "bg-slate-100 text-slate-700 hover:bg-slate-200"
          }`}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

export function HealthInsuranceCoverageGapsCensus2026Dashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [expansion, setExpansion] = useState<ExpansionFilter>("all");
  const [ladderSort, setLadderSort] = useState<LadderSort>("rate");

  const filtered = useMemo(() => {
    const byRegion = statesByRegion(region);
    if (expansion === "all") return byRegion;
    return byRegion.filter((s) => s.expansion === expansion);
  }, [region, expansion]);

  const ladderData = useMemo(() => {
    const rows = [...filtered];
    if (ladderSort === "rate") rows.sort((a, b) => b.rate2024 - a.rate2024);
    else if (ladderSort === "delta")
      rows.sort((a, b) => b.deltaPp - a.deltaPp);
    else rows.sort((a, b) => b.uninsuredM - a.uninsuredM);
    return rows.slice(0, 25).map((s) => ({
      ...s,
      fill:
        s.expansion === "non-expansion"
          ? ROSE
          : REGION_COLORS[s.region] || TEAL,
      label: s.abbr,
    }));
  }, [filtered, ladderSort]);

  const scatterData = useMemo(
    () =>
      filtered.map((s) => ({
        ...s,
        x: s.rate2023,
        y: s.deltaPp,
        z: Math.max(40, Math.min(320, s.uninsuredM * 60)),
        fill:
          s.expansion === "non-expansion"
            ? ROSE
            : REGION_COLORS[s.region] || TEAL,
      })),
    [filtered],
  );

  const movesData = useMemo(
    () =>
      BIGGEST_MOVES.map((m) => ({
        ...m,
        fill: m.direction === "up" ? ROSE : TEAL,
      })),
    [],
  );

  return (
    <div
      className="w-full min-w-0 space-y-4"
      data-viz="health-insurance-coverage-gaps-census-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-teal-950 px-5 py-4 text-white shadow-sm">
        <p className="text-xs font-semibold uppercase tracking-wider text-teal-300">
          Census ACS ?? working-age adults 19???64
        </p>
        <p className="mt-1 text-lg font-bold sm:text-xl">
          {VIZ_MARKERS[0]} ?? national {fmtPct(HEADLINE.usWorkingAge2024)}
        </p>
        <p className="mt-1 text-sm text-slate-300">
          {HEADLINE.statesSigIncrease} jurisdictions rose significantly after
          Medicaid continuous enrollment ended; {HEADLINE.statesSigDecrease}{" "}
          fell. Non-expansion tape still clears near {fmtPct(16.8)}.
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup<ViewId>
          value={view}
          onChange={setView}
          options={[
            { id: "ladder", label: "State ladder" },
            { id: "scatter", label: "Unwinding delta" },
            { id: "vintage", label: "National path" },
            { id: "expansion", label: "Expansion gap" },
            { id: "ages", label: "Age & race" },
            { id: "moves", label: "Biggest movers" },
          ]}
        />
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center">
        <ToggleGroup<RegionFilter>
          value={region}
          onChange={setRegion}
          options={[
            { id: "all", label: "All regions" },
            { id: "South", label: "South" },
            { id: "Midwest", label: "Midwest" },
            { id: "West", label: "West" },
            { id: "Northeast", label: "Northeast" },
          ]}
        />
        <ToggleGroup<ExpansionFilter>
          value={expansion}
          onChange={setExpansion}
          options={[
            { id: "all", label: "All expansion" },
            { id: "expanded", label: "Expanded" },
            { id: "non-expansion", label: "Non-expansion" },
          ]}
        />
        {view === "ladder" && (
          <ToggleGroup<LadderSort>
            value={ladderSort}
            onChange={setLadderSort}
            options={[
              { id: "rate", label: "Sort by rate" },
              { id: "delta", label: "Sort by delta" },
              { id: "headcount", label: "Sort by headcount" },
            ]}
          />
        )}
      </div>

      {view === "ladder" && (
        <ChartCard
          title="State ladder vs national 11.3%"
          subtitle="ACS working-age (19???64) uninsured rate, 2024. Rose = non-expansion as of Jan 1, 2024."
        >
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={ladderData}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 24]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fill: SLATE, fontSize: 11 }}
                />
                <YAxis
                  type="category"
                  dataKey="label"
                  width={36}
                  tick={{ fill: NAVY, fontSize: 11 }}
                />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0].payload;
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow">
                        <p className="font-semibold text-slate-900">{d.state}</p>
                        <p>2024: {fmtPct(d.rate2024)}</p>
                        <p>?? 2023???24: {fmtPp(d.deltaPp)}</p>
                        <p>~{d.uninsuredM.toFixed(2)}M uninsured (est.)</p>
                      </div>
                    );
                  }}
                />
                <ReferenceLine
                  x={HEADLINE.usWorkingAge2024}
                  stroke={SKY}
                  strokeDasharray="4 4"
                  label={{
                    value: VIZ_MARKERS[1],
                    position: "insideTopRight",
                    fill: SKY,
                    fontSize: 10,
                  }}
                />
                <Bar dataKey="rate2024" radius={[0, 4, 4, 0]}>
                  {ladderData.map((row) => (
                    <Cell key={row.abbr} fill={row.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Unwinding delta scatter"
          subtitle="X = 2023 working-age rate; Y = 2023???2024 pp change. Bubble size ??? estimated uninsured headcount."
        >
          <div className="h-[440px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 16, right: 24, left: 8, bottom: 16 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="2023 rate"
                  unit="%"
                  domain={[2, 24]}
                  tick={{ fill: SLATE, fontSize: 11 }}
                  label={{
                    value: "2023 uninsured %",
                    position: "insideBottom",
                    offset: -4,
                    fill: SLATE,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="delta"
                  domain={[-1.8, 2.6]}
                  tick={{ fill: SLATE, fontSize: 11 }}
                  label={{
                    value: "pp change",
                    angle: -90,
                    position: "insideLeft",
                    fill: SLATE,
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[40, 320]} />
                <ReferenceLine y={0} stroke={SLATE} strokeDasharray="3 3" />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0].payload;
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow">
                        <p className="font-semibold">{d.state}</p>
                        <p>
                          {fmtPct(d.rate2023)} ??? {fmtPct(d.rate2024)} (
                          {fmtPp(d.deltaPp)})
                        </p>
                        <p>
                          {d.significant ? "Significant" : "Not significant"} @
                          90%
                        </p>
                      </div>
                    );
                  }}
                />
                <Scatter data={scatterData} name={VIZ_MARKERS[2]}>
                  {scatterData.map((row) => (
                    <Cell key={row.abbr} fill={row.fill} fillOpacity={0.85} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "vintage" && (
        <ChartCard
          title="National path through continuous enrollment"
          subtitle="Working-age uninsured % (left) vs Medicaid coverage share all ages (right). 2019???22 carried ACS context; 2023???24 disclosed ACSBR-024."
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={NATIONAL_VINTAGE}
                margin={{ top: 16, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fill: SLATE, fontSize: 11 }} />
                <YAxis
                  yAxisId="left"
                  domain={[7, 14]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fill: SLATE, fontSize: 11 }}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  domain={[18, 23]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fill: SLATE, fontSize: 11 }}
                />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0].payload;
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow">
                        <p className="font-semibold">{d.year}</p>
                        <p>Working-age: {fmtPct(d.workingAgePct)}</p>
                        <p>All ages: {fmtPct(d.allAgesPct)}</p>
                        <p>Medicaid: {fmtPct(d.medicaidPct)}</p>
                        <p className="text-slate-500">{d.note}</p>
                      </div>
                    );
                  }}
                />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="workingAgePct"
                  name="Working-age uninsured %"
                  fill={TEAL}
                  fillOpacity={0.2}
                  stroke={TEAL}
                  strokeWidth={2}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="medicaidPct"
                  name="Medicaid share %"
                  stroke={AMBER}
                  strokeWidth={2.5}
                  dot={{ r: 4 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "expansion" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Expansion gap"
            subtitle="Population-weighted desk means of ACS working-age rates by Jan 2024 expansion status."
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={EXPANSION_COMPARE}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="group"
                    tick={{ fill: SLATE, fontSize: 10 }}
                    interval={0}
                    angle={-12}
                    textAnchor="end"
                    height={70}
                  />
                  <YAxis
                    domain={[0, 20]}
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fill: SLATE, fontSize: 11 }}
                  />
                  <Tooltip
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const d = payload[0].payload;
                      return (
                        <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow">
                          <p className="font-semibold">{d.group}</p>
                          <p>{fmtPct(d.rate2024)}</p>
                          <p>{d.states} jurisdictions</p>
                          <p className="text-slate-500">{d.note}</p>
                        </div>
                      );
                    }}
                  />
                  <Bar dataKey="rate2024" radius={[6, 6, 0, 0]}>
                    {EXPANSION_COMPARE.map((row) => (
                      <Cell
                        key={row.group}
                        fill={
                          row.group.startsWith("Non")
                            ? ROSE
                            : row.group.startsWith("United")
                              ? SKY
                              : TEAL
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Regional means"
            subtitle="Simple unweighted mean of state working-age rates within Census region."
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={REGION_SUMMARY}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="region" tick={{ fill: SLATE, fontSize: 11 }} />
                  <YAxis
                    domain={[0, 16]}
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fill: SLATE, fontSize: 11 }}
                  />
                  <Tooltip
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const d = payload[0].payload;
                      return (
                        <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow">
                          <p className="font-semibold">{d.region}</p>
                          <p>Mean rate: {fmtPct(d.meanRate2024)}</p>
                          <p>Mean ??: {fmtPp(d.meanDeltaPp)}</p>
                          <p>
                            Above national: {d.statesAboveNational} ?? peak{" "}
                            {d.topState} {fmtPct(d.topRate)}
                          </p>
                        </div>
                      );
                    }}
                  />
                  <Bar dataKey="meanRate2024" radius={[6, 6, 0, 0]}>
                    {REGION_SUMMARY.map((row) => (
                      <Cell
                        key={row.region}
                        fill={REGION_COLORS[row.region]}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "ages" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Age bands (CPS ASEC 2024)"
            subtitle="Working-age uninsured falls with age. 26???34 band estimated from adjacent disclosed bands."
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={AGE_BANDS}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="band" tick={{ fill: SLATE, fontSize: 11 }} />
                  <YAxis
                    domain={[0, 16]}
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fill: SLATE, fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar
                    dataKey="rate2024"
                    fill={INDIGO}
                    radius={[6, 6, 0, 0]}
                    name="Uninsured %"
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Race & ethnicity (CPS ASEC 2024)"
            subtitle="Working-age adults 19???64. Hispanic rate remains more than triple White non-Hispanic."
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={DEMO_GAPS}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 26]}
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fill: SLATE, fontSize: 11 }}
                  />
                  <YAxis
                    type="category"
                    dataKey="group"
                    width={120}
                    tick={{ fill: NAVY, fontSize: 10 }}
                  />
                  <Tooltip />
                  <Bar
                    dataKey="rate2024"
                    fill={AMBER}
                    radius={[0, 6, 6, 0]}
                    name="Uninsured %"
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "moves" && (
        <ChartCard
          title="Biggest movers 2023???2024"
          subtitle="Largest absolute working-age pp changes (significant ACS changes or |??| ??? 1.0)."
        >
          <div className="h-[440px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={movesData}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[-1.6, 2.4]}
                  tickFormatter={(v) => `${v > 0 ? "+" : ""}${v}`}
                  tick={{ fill: SLATE, fontSize: 11 }}
                />
                <YAxis
                  type="category"
                  dataKey="abbr"
                  width={36}
                  tick={{ fill: NAVY, fontSize: 11 }}
                />
                <ReferenceLine x={0} stroke={SLATE} />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0].payload;
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow">
                        <p className="font-semibold">{d.state}</p>
                        <p>{fmtPp(d.deltaPp)}</p>
                        <p>2024 rate: {fmtPct(d.rate2024)}</p>
                      </div>
                    );
                  }}
                />
                <Bar dataKey="deltaPp" radius={[0, 4, 4, 0]}>
                  {movesData.map((row) => (
                    <Cell key={row.abbr} fill={row.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="sr-only">
        {statesByExpansion("non-expansion").length} non-expansion states in
        filter set; {STATE_GAPS.length} jurisdictions total.
      </p>
    </div>
  );
}

