import { chromium } from 'playwright';
import { startStaticServer, stopStaticServer } from './scripts/lib/static-server.mjs';
const port = 4182;
const server = await startStaticServer('out', port);
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.goto('http://127.0.0.1:'+port+'/blog/health-insurance-coverage-gaps-census-2026.html', { waitUntil: 'domcontentloaded', timeout: 45000 });
await page.waitForSelector('[data-viz=\"health-insurance-coverage-gaps-census-2026\"]', { timeout: 20000 });
await page.getByText('Working-age uninsured ??? Texas 21.6%', { exact: false }).first().waitFor({ state: 'attached', timeout: 15000 });
console.log('smoke ok');
await browser.close();
await stopStaticServer(server);
"; git add -A; git status -sb; git log -3 --oneline

